-- The existing editor and local expert map now use Supabase Auth + Postgres.
alter table public.posts
  add column images text[] not null default '{}',
  add column font text check (font in ('sans', 'serif')),
  add column font_size smallint not null default 16 check (font_size in (14, 16, 18)),
  add column legacy_id uuid unique;

create function public.valid_external_images(urls text[]) returns boolean
language sql immutable set search_path = public as $$
  select coalesce(array_ndims(urls), 1) = 1 and cardinality(urls) <= 5
    and not exists (select 1 from unnest(urls) as image_url
      where image_url is null or char_length(image_url) > 2048
        or image_url !~ '^https://i[.]ibb[.]co/[^/?#]');
$$;
alter table public.posts add constraint posts_external_images_check check (public.valid_external_images(images));
alter table public.posts add constraint posts_editor_title_check check (char_length(btrim(title)) between 1 and 100);
alter table public.posts add constraint posts_editor_body_check check (char_length(btrim(body)) between 1 and 5000);

insert into public.boards (slug, name, sort_order) values
  ('foliage', '觀葉植物', 1), ('succulents', '多肉植物', 2),
  ('herbs', '香草植物', 3), ('flowers', '花卉植物', 4)
on conflict (slug) do nothing;

create table public.taiwan_regions (
  code text primary key,
  county text not null,
  district text not null
);
alter table public.taiwan_regions enable row level security;
create policy taiwan_regions_read on public.taiwan_regions for select using (true);

create table public.expert_columns (
  id uuid primary key default gen_random_uuid(),
  author_id uuid not null references public.profiles(id),
  title text not null check (char_length(btrim(title)) between 1 and 100),
  excerpt text not null check (char_length(btrim(excerpt)) between 1 and 200),
  body text not null check (char_length(btrim(body)) between 1 and 5000),
  region_code text not null references public.taiwan_regions(code),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index expert_columns_region_idx on public.expert_columns(region_code);
create index expert_columns_author_idx on public.expert_columns(author_id);
create index expert_columns_created_idx on public.expert_columns(created_at desc, id);
create trigger expert_columns_updated_at before update on public.expert_columns
  for each row execute function public.set_updated_at();
alter table public.expert_columns enable row level security;
create policy expert_columns_read on public.expert_columns for select using (true);
create policy expert_columns_insert on public.expert_columns for insert to authenticated with check (author_id = auth.uid());
create policy expert_columns_update on public.expert_columns for update to authenticated
  using (author_id = auth.uid() or public.is_moderator())
  with check (author_id = auth.uid() or public.is_moderator());

-- Never accept a role from signup metadata, and bound display names in Auth's trigger too.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, username, display_name) values (
    new.id, 'user_' || substr(md5(new.id::text), 1, 15),
    left(coalesce(nullif(btrim(new.raw_user_meta_data->>'name'), ''), '新會員'), 40)
  );
  return new;
end $$;
insert into public.profiles (id, username, display_name)
select id, 'user_' || substr(md5(id::text), 1, 15),
  left(coalesce(nullif(btrim(raw_user_meta_data->>'name'), ''), '新會員'), 40)
from auth.users on conflict (id) do nothing;
revoke execute on function public.handle_new_user() from public, anon, authenticated;

-- Grants are explicit instead of depending on a project's default privileges.
revoke all on public.profiles, public.posts, public.expert_columns, public.taiwan_regions from anon, authenticated;
grant usage on schema public to anon, authenticated;
grant select on public.profiles, public.boards, public.species, public.tags, public.posts,
  public.post_species, public.post_tags, public.replies, public.post_likes, public.reply_likes,
  public.images, public.expert_columns, public.taiwan_regions to anon, authenticated;
grant update (username, display_name, avatar_url, bio, region) on public.profiles to authenticated;
grant insert (board_id, author_id, post_type, region, title, body, images, font, font_size) on public.posts to authenticated;
grant update (board_id, post_type, region, title, body, images, font, font_size,
  deleted_at, accepted_reply_id, is_pinned, is_locked) on public.posts to authenticated;
grant insert (author_id, title, excerpt, body, region_code) on public.expert_columns to authenticated;
grant update (title, excerpt, body, region_code) on public.expert_columns to authenticated;
grant usage, select on all sequences in schema public to authenticated;

